// x87 and MMX helpers for code generated by xlat/emit_x87.py.
//
// The register stack holds doubles: MSVC runs x87 at 53-bit precision (control word 0x27f), so
// arithmetic rounds like double already; only the 15-bit exponent range (overflow/underflow
// between double and extended range) and 64-bit integers above 2^53 differ. Rounding control
// is honoured where the result is an integer (fist/fistp, frndint); arithmetic rounds to
// nearest. Exceptions are not raised and their status bits are not set (fnstsw reads 0 for
// them); stack overflow/underflow are not detected, as on the Unicorn/QEMU reference.
//
// MMX registers are kept apart from the x87 ones (c->fpu.mm): an MMX instruction sets TOP to 0
// and every tag to valid, emms every tag to empty, as on hardware, but the bits of the mm
// registers are not visible through st(i) (code does not mix the two without emms).
#ifndef RC32_X87_H
#define RC32_X87_H
#include <math.h>
#include "rc32.h"

#define RC87_C0 0x0100
#define RC87_C1 0x0200
#define RC87_C2 0x0400
#define RC87_C3 0x4000
#define RC87_CC (RC87_C0 | RC87_C1 | RC87_C2 | RC87_C3)

#define ST(k) (c->fpu.st[(c->fpu.top + (k)) & 7])

static inline void rc87_push(rc_ctx *c, double v) {
  c->fpu.top = (c->fpu.top - 1) & 7;
  c->fpu.st[c->fpu.top] = v;
  c->fpu.tag &= ~(1u << c->fpu.top);
}
static inline void rc87_pop(rc_ctx *c) {
  c->fpu.tag |= 1u << c->fpu.top;
  c->fpu.top = (c->fpu.top + 1) & 7;
}
static inline void rc87_setcc(rc_ctx *c, uint16_t cc) { c->fpu.sw = (c->fpu.sw & ~RC87_CC) | cc; }
// fcom/fucom/ficom/ftst: C3 C2 C0 = 000 greater, 001 less, 100 equal, 111 unordered; C1 = 0.
static inline void rc87_cmp(rc_ctx *c, double a, double b) {
  rc87_setcc(c, a != a || b != b ? (RC87_C0 | RC87_C2 | RC87_C3)
                : a < b ? RC87_C0 : a == b ? RC87_C3 : 0);
}
static inline uint16_t rc87_fnstsw(const rc_ctx *c) {
  return (uint16_t)((c->fpu.sw & ~0x3800) | ((c->fpu.top & 7) << 11));
}
static inline void rc87_fldsw(rc_ctx *c, uint16_t v) {
  c->fpu.sw = v & ~0x3800;
  c->fpu.top = (v >> 11) & 7;
}
static inline void rc87_init(rc_ctx *c) {
  c->fpu.cw = 0x37f;
  c->fpu.sw = 0;
  c->fpu.top = 0;
  c->fpu.tag = 0xff;
}
// fxam: class in C3 C2 C0, sign in C1. A double held here is never an x87 denormal or
// unsupported encoding (an x87 holds every double denormal as a normal number).
static inline void rc87_fxam(rc_ctx *c) {
  double v = ST(0);
  uint16_t s = signbit(v) ? RC87_C1 : 0;
  if (c->fpu.tag & (1u << c->fpu.top)) rc87_setcc(c, RC87_C3 | RC87_C0 | s);
  else if (v != v) rc87_setcc(c, RC87_C0 | s);
  else if (isinf(v)) rc87_setcc(c, RC87_C2 | RC87_C0 | s);
  else if (v == 0) rc87_setcc(c, RC87_C3 | s);
  else rc87_setcc(c, RC87_C2 | s);
}

// Round to an integer by the control word's rounding field.
static inline double rc87_round(const rc_ctx *c, double v) {
  switch ((c->fpu.cw >> 10) & 3) {
    case 0: return __builtin_roundeven(v);
    case 1: return floor(v);
    case 2: return ceil(v);
    default: return trunc(v);
  }
}
// fist/fistp/fisttp: out of range or NaN stores the integer indefinite (the most negative value).
static inline int16_t rc87_i16(double r) { return (r >= -32768.0 && r <= 32767.0) ? (int16_t)r : INT16_MIN; }
static inline int32_t rc87_i32(double r) {
  return (r >= -2147483648.0 && r <= 2147483647.0) ? (int32_t)r : INT32_MIN;
}
static inline int64_t rc87_i64(double r) {
  return (r >= -9223372036854775808.0 && r < 9223372036854775808.0) ? (int64_t)r : INT64_MIN;
}

// 80-bit extended <-> double (fld/fstp tbyte, fnsave/frstor).
static inline double rc87_from80(const uint8_t *p) {
  uint64_t m;
  uint16_t se;
  memcpy(&m, p, 8);
  memcpy(&se, p + 8, 2);
  int e = se & 0x7fff;
  double s = (se & 0x8000) ? -1.0 : 1.0;
  if (e == 0x7fff) return (m << 1) ? s * NAN : s * INFINITY;
  if (m == 0) return s * 0.0;
  return s * ldexp((double)m, (e ? e : 1) - 16383 - 63);
}
static inline void rc87_to80(uint8_t *p, double v) {
  uint64_t m = 0;
  uint16_t se = signbit(v) ? 0x8000 : 0;
  if (v != v) { m = 0xc000000000000000ull; se |= 0x7fff; }
  else if (isinf(v)) { m = 0x8000000000000000ull; se |= 0x7fff; }
  else if (v != 0) {
    int e;
    double f = frexp(fabs(v), &e);           // f in [0.5, 1)
    m = (uint64_t)ldexp(f, 64);              // exact: a double has 53 significant bits
    se |= (uint16_t)(e - 1 + 16383);
  }
  memcpy(p, &m, 8);
  memcpy(p + 8, &se, 2);
}

// Tag word in the 16-bit format of fnstenv/fnsave (2 bits per physical register:
// 00 valid, 01 zero, 10 special, 11 empty).
static inline uint16_t rc87_tagword(const rc_ctx *c) {
  uint16_t t = 0;
  for (int k = 0; k < 8; k++) {
    unsigned v;
    double x = c->fpu.st[k];
    if (c->fpu.tag & (1u << k)) v = 3;
    else if (x == 0) v = 1;
    else if (x != x || isinf(x)) v = 2;
    else v = 0;
    t |= (uint16_t)(v << (2 * k));
  }
  return t;
}
// fnstenv / fldenv, 32-bit protected-mode layout (28 bytes); instruction and operand pointers 0.
static inline void rc87_fnstenv(rc_ctx *c, uint8_t *p) {
  uint32_t w[7] = {c->fpu.cw, rc87_fnstsw(c), rc87_tagword(c), 0, 0, 0, 0};
  memcpy(p, w, 28);
}
static inline void rc87_fldenv(rc_ctx *c, const uint8_t *p) {
  uint32_t w[3];
  memcpy(w, p, 12);
  c->fpu.cw = (uint16_t)w[0];
  rc87_fldsw(c, (uint16_t)w[1]);
  c->fpu.tag = 0;
  for (int k = 0; k < 8; k++)
    if (((w[2] >> (2 * k)) & 3) == 3) c->fpu.tag |= 1u << k;
}
static inline void rc87_fnsave(rc_ctx *c, uint8_t *p) {
  rc87_fnstenv(c, p);
  for (int k = 0; k < 8; k++) rc87_to80(p + 28 + 10 * k, ST(k));
  rc87_init(c);
}
static inline void rc87_frstor(rc_ctx *c, const uint8_t *p) {
  rc87_fldenv(c, p);
  for (int k = 0; k < 8; k++) ST(k) = rc87_from80(p + 28 + 10 * k);
}

// fprem / fprem1: complete reduction (C2 = 0) with the low three quotient bits in C0 C3 C1.
static inline void rc87_fprem(rc_ctx *c, int ieee) {
  double a = ST(0), b = ST(1);
  double r = ieee ? remainder(a, b) : fmod(a, b);
  double q = (a - r) / b;
  uint64_t qi = (q == q && fabs(q) < 18446744073709551616.0) ? (uint64_t)fabs(q) : 0;
  uint16_t cc = 0;
  if (qi & 1) cc |= RC87_C1;
  if (qi & 2) cc |= RC87_C3;
  if (qi & 4) cc |= RC87_C0;
  rc87_setcc(c, cc);
  ST(0) = r;
}
static inline void rc87_fxtract(rc_ctx *c) {
  double v = ST(0);
  if (v == 0) {
    ST(0) = -INFINITY;
    rc87_push(c, v);
    return;
  }
  if (v != v || isinf(v)) {
    ST(0) = v != v ? v : INFINITY;
    rc87_push(c, v);
    return;
  }
  int e;
  double f = frexp(v, &e);
  ST(0) = (double)(e - 1);
  rc87_push(c, f * 2.0);
}
// fptan/fsin/fcos/fsincos leave operands outside +-2^63 unchanged with C2 = 1.
static inline int rc87_trig_ok(rc_ctx *c) {
  if (fabs(ST(0)) >= 9223372036854775808.0) {
    rc87_setcc(c, (c->fpu.sw & (RC87_C0 | RC87_C3)) | RC87_C2);
    return 0;
  }
  c->fpu.sw &= ~(RC87_C1 | RC87_C2);
  return 1;
}

// MMX: every MMX instruction (except emms) makes the whole stack valid with TOP = 0.
static inline void rc87_mmx(rc_ctx *c) {
  c->fpu.top = 0;
  c->fpu.tag = 0;
}
// pshufw (MMX): words of a picked by the 2-bit fields of imm.
static inline uint64_t rc_pshufw64(uint64_t a, int imm) {
  uint64_t r = 0;
  for (int k = 0; k < 4; k++) r |= ((a >> (16 * ((imm >> (2 * k)) & 3))) & 0xffff) << (16 * k);
  return r;
}

#endif
